import{_ as i,l as s,o as r,c as l,v as e,p as n,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"PLA 与 ROM 作组合","description":"","frontmatter":{"title":"PLA 与 ROM 作组合","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pla-rom.md","filePath":"cs/pla-rom.md","lastUpdated":1789023840000}'),A={name:"cs/pla-rom.md"};function h(m,a,E,_,P,R){const o=s("Mermaid");return r(),l("div",null,[a[1]||(a[1]=e('<h1 id="pla-与-rom-作组合" tabindex="-1">PLA 与 ROM 作组合 <a class="header-anchor" href="#pla-与-rom-作组合" aria-label="Permalink to &quot;PLA 与 ROM 作组合&quot;">​</a></h1><div class="epigraph"><p>任意真值表不必化成最少门：ROM 按地址读出函数值，PLA 烧与项再或起来，都是组合，只是实现形态不同。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/comparator-circuit">比较器</a>把 eq / 有符号 / 无符号三种比较收成组合块。从<a href="/cs/cmos-inverter">反相器</a>到比较，主干一直在拼门。本课不重接线旗标，也不从 FPGA LUT 架构史另起。缺口是：有些函数（控制器、不规则译码）用两级<strong>可编程与-或</strong>或一张表更自然。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>规范 SOP 是与项的或。PLA：可编程与阵列生成乘积项，或阵列把项送到各输出。ROM：地址即输入，每个地址存输出字，功能是「完整真值表」。缺口不是新的布尔公理，而是承认组合逻辑有<strong>表驱动</strong>实现，后课微程序、控制 ROM 用同一直觉。</p><p>PLA 不必列出全部 \\(2^n\\) 最小项，只烧需要的积项。ROM 在输入变宽时指数爆炸，只适合输入少、输出不规则。</p><h3 id="rom-不是存储器课的「可写主存」" tabindex="-1">ROM 不是存储器课的「可写主存」 <a class="header-anchor" href="#rom-不是存储器课的「可写主存」" aria-label="Permalink to &quot;ROM 不是存储器课的「可写主存」&quot;">​</a></h3><p>这里的 ROM 是组合查表：地址变，数据在 \\(t_{pd}\\) 后稳，没有写口、没有刷新。后课<a href="/cs/memory-array-sram-dram">SRAM/DRAM 阵列</a>才是可写存储。把本课 ROM 当成 DRAM，时序单元会提前出场。</p><p><span class="marginnote">Harris 用 PLA 实现有限状态机的下一态与输出——那是时序课；本课先当纯组合。PROM/EEPROM 的浮栅是工艺，功能仍是表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>输入经缓冲与反相，进与平面；积项进或平面得输出。ROM：译码器点一行，位线给出预存比特。两者都有明确 \\(t_{pd}\\)，计入<a href="/cs/critical-path">关键路径</a>。</p>',11)),(r(),n(c,null,{default:t(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%B8%83%E5%B0%94%E5%87%BD%E6%95%B0%22%5D%20--%3E%20GATES%5B%22%E9%97%A8%E7%BD%91%20%2F%20%E6%A0%87%E5%87%86%E5%8D%95%E5%85%83%22%5D%0A%20%20F%20--%3E%20PLA%5B%22%E4%B8%8E%E9%A1%B9%E5%8A%A0%E6%88%96%E9%A1%B9%22%5D%0A%20%20F%20--%3E%20ROM%5B%22%E5%9C%B0%E5%9D%80%E6%9F%A5%E8%A1%A8%22%5D%0A%20%20ROM%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%9C%80%E8%A6%81%E8%AE%B0%E5%BF%86%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>比较器、ALU 用结构块更省。不规则控制（「这些 opcode 组合才置这一位」）用 ROM/PLA 更直。后课单周期控制器真值表可以落成 PLA 或 ROM，仍是组合 \\(y=f(\\mathrm{opcode})\\)。组合主干到此收束：功能可门可表；下一课开始状态。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 FPGA 的 LUT 与可重配置互连，那是另一封装。不把闪存文件系统当 ROM 组合。时序电路仍未出现。</p><p>后课默认：任意组合函数可用门网、PLA 或 ROM 实现；下一课锁存与触发器才有记忆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PLA 烧 SOP；ROM 存真值表；都是组合。</li><li>输入宽时 ROM 不划算；规则运算仍用加法器等结构块。</li><li>可写存储器是后课阵列，不是本课的 ROM。</li><li>出处：Harris and Harris。</li></ul>',7))])}const O=i(A,[["render",h]]);export{u as __pageData,O as default};
